-- Generated by scripts/build.py. Edit src/*.luau, then rebuild.
local Core = (function()
-- Pure automation controller. Adapter calls must not yield; Roblox lookups live in Hub.luau.
local Core = {}
Core.__index = Core
Core.ARRIVAL_RADIUS = 50
Core.ARRIVAL_SETTLE = 1.5
Core.ARRIVAL_RETRY = 3
Core.ARRIVAL_ATTEMPTS = 5
Core.RECOVERY_DELAY = 3
Core.ARRIVAL_RECOVERY_DELAY = 10

-- Reward/eligibility data supplied from JobsConfig / JobRewards (2026-10-31).
Core.JOBS = {
    { tier = 4, jobType = 1, name = "Extreme", reward = 40000, ascensions = 75 },
    { tier = 10, jobType = 2, name = "Ancient Crystal", reward = 25000, ascensions = 50 },
    { tier = 7, jobType = 1, name = "Long-Haul Cargo", reward = 18000, ascensions = 30 },
    { tier = 9, jobType = 2, name = "Crystal Core", reward = 14000, ascensions = 25 },
    { tier = 3, jobType = 1, name = "Hard", reward = 10000, ascensions = 10 },
    { tier = 6, jobType = 1, name = "City Express", reward = 10000, ascensions = 12 },
    { tier = 8, jobType = 2, name = "Crystal Shards", reward = 6000, ascensions = 8 },
    { tier = 2, jobType = 1, name = "Medium", reward = 5000, ascensions = 4 },
    { tier = 5, jobType = 1, name = "Supply Rush", reward = 4000, ascensions = 3 },
    { tier = 1, jobType = 1, name = "Easy", reward = 1000, ascensions = 0 },
}

function Core.bestJob(ascensions)
    assert(type(ascensions) == "number" and ascensions >= 0 and ascensions < math.huge and ascensions % 1 == 0,
        "Ascension count unavailable · enter your current count on Jobs")
    local best
    for _, candidate in ipairs(Core.JOBS) do
        if ascensions >= candidate.ascensions and (not best or candidate.reward > best.reward
            or candidate.reward == best.reward and candidate.ascensions < best.ascensions) then
            best = candidate
        end
    end
    return best
end

function Core.new(adapter)
    return setmetatable({
        adapter = adapter,
        running = true,
        mode = nil,
        treadmill = "x10",
        enabled = { race = false, ascend = false, buy = false, antiIdle = true },
        status = {},
        due = {},
        failures = {},
        jobs = { phase = "idle" },
        farmPhase = "start",
        deliveries = 0,
        orbRequests = 0,
    }, Core)
end

function Core:report(key, text, problem, issue)
    local old = self.status[key]
    if not old or old.text ~= text or old.problem ~= (problem == true) or old.issue ~= issue then
        self.status[key] = { text = text, problem = problem == true, issue = issue }
        if self.adapter.onStatus then
            self.adapter.onStatus(key, text, problem == true, issue)
        end
    end
end

function Core:setMode(mode)
    assert(mode == nil or mode == "farm" or mode == "orbs" or mode == "jobs", "Unknown movement mode")
    if not self.running or self.mode == mode then return end
    if self.mode == "jobs" and self.adapter.stopDeliveryMovement then
        self.adapter.stopDeliveryMovement()
    end
    if self.mode then self:report(self.mode, "Off") end
    self.mode = mode
    self.jobs = { phase = "idle" }
    self.farmPhase = "start"
    self.due.movement = 0
    self.failures.movement = 0
    if mode then self:report(mode, "Starting…") end
end

function Core:setEnabled(key, value)
    assert(self.enabled[key] ~= nil, "Unknown automation")
    if not self.running then return end
    self.enabled[key] = value == true
    self.due[key] = 0
    self.failures[key] = 0
    self:report(key, value and "Ready" or "Off")
end

function Core:stopAll()
    self:setMode(nil)
    for key in pairs(self.enabled) do self:setEnabled(key, false) end
end

function Core:destroy()
    if not self.running then return end
    self:stopAll()
    self.running = false
end

function Core:run(key, statusKey, now, callback)
    if now < (self.due[key] or 0) then return end
    local ok, delay = pcall(callback)
    if ok then
        self.failures[key] = 0
        self.due[key] = now + (delay or 1)
    else
        if statusKey == "jobs" then
            self.adapter.stopDeliveryMovement()
            -- An unreadable sample is not evidence of continuous proximity/completion.
            if self.jobs.travel then self.jobs.travel.withinSince = nil end
        end
        local failures = (self.failures[key] or 0) + 1
        self.failures[key] = failures
        local retry = math.min(15, 2 ^ math.min(failures - 1, 4))
        self.due[key] = now + retry
        self:report(statusKey, tostring(delay) .. " · retry in " .. retry .. "s", true)
    end
end

function Core:recoverMovement(phase, drop)
    if self.adapter.recoverJobMovement then
        self.adapter.recoverJobMovement(phase, drop)
    elseif phase == "running" then
        self.adapter.moveToDrop(drop)
    elseif phase == "claimed" then
        self.adapter.leaveJobPad()
    else
        self.adapter.moveToBoard()
    end
end

local function recoveryDelay(attempts)
    return math.min(30, Core.RECOVERY_DELAY * 2 ^ math.min(attempts or 0, 4))
end

function Core:travelToBoard(now, job, gamePhase)
    if job.boardPaused then
        if now < job.boardRetryAt then
            self:report("jobs", "Board travel stalled · retrying automatically", true, "board_stalled")
            return false
        end
        job.boardRecoveries = (job.boardRecoveries or 0) + 1
        job.boardPaused = nil
        job.bestBoardDistance = nil
        job.boardProgressAt = now
        job.spawnRequested = nil
        job.spawnFinished = nil
        job.boardNeedsRecovery = true
    end
    if self.adapter.shouldReturnToSpawn and self.adapter.shouldReturnToSpawn() and not job.spawnRequested then
        self.adapter.stopDeliveryMovement()
        self.adapter.returnToSpawn()
        job.spawnRequested = now
        self:report("jobs", "Return to Spawn requested · waiting for the game")
        return false
    end
    if job.spawnRequested and not job.spawnFinished then
        if not self.adapter.hasReturnedToSpawn() and now - job.spawnRequested < 5 then
            self:report("jobs", "Waiting for Return to Spawn")
            return false
        end
        -- A missing acknowledgement must not deadlock travel; approach normally after the grace period.
        job.spawnFinished = true
        job.boardProgressAt = now
        job.bestBoardDistance = nil
    end
    -- A spawn request stops steering. Start route recovery only after it settles,
    -- otherwise stopping for the request discards the new route before it runs.
    if job.boardNeedsRecovery then
        self:recoverMovement("idle")
        job.boardNeedsRecovery = nil
    end
    local reached, distance = self.adapter.moveToBoard(gamePhase)
    if reached ~= false then return true end
    job.bestBoardDistance = job.bestBoardDistance or distance
    job.boardProgressAt = job.boardProgressAt or now
    if distance < job.bestBoardDistance - 2 then
        job.bestBoardDistance = distance
        job.boardProgressAt = now
    end
    if now - job.boardProgressAt >= 12 then
        self.adapter.stopDeliveryMovement()
        job.boardPaused = true
        job.boardRetryAt = now + recoveryDelay(job.boardRecoveries)
    end
    self:report("jobs", string.format("Travelling to job board · %.0f studs remaining", distance))
    return false
end

function Core.chainCapacity(ascensions)
    Core.bestJob(ascensions) -- Reuse finite, whole-number validation.
    if ascensions >= 25 then return 4 end
    if ascensions >= 10 then return 3 end
    return 2
end

function Core:stepJobs(now)
    local job = self.jobs
    local state = self.adapter.getJobState()
    assert(type(state) == "table" and (state.phase == "idle" or state.phase == "claimed" or state.phase == "running"), "Waiting for a valid job phase")
    for _, key in ipairs({ "legCount", "banked", "index", "revision" }) do
        local value = state[key]
        assert(type(value) == "number" and value >= 0 and value < math.huge and value % 1 == 0, "Invalid job state: " .. key)
    end
    assert(state.legCount <= 4 and state.index <= state.legCount + 1, "Invalid job chain")
    assert(type(state.delivered) == "boolean", "Delivery acknowledgement unavailable")
    assert(state.phase ~= "running" or state.legCount > 0 and state.index >= 1, "Waiting for the active chain index")
    self.jobState = state
    if state.phase == "idle" then job.departingToSpawn = nil end
    if state.phase ~= "claimed" and not job.departingToSpawn then
        job.leaveStarted, job.nextLeave, job.leaveRetryAt, job.leaveRecoveries, job.departurePhase = nil, nil, nil, nil, nil
    end

    local pending = job.pendingClaim
    if pending and (state.legCount > pending.before or state.phase == "running") then
        job.pendingClaim = nil
        job.claimReadyAt = nil
    end
    if job.pendingCollect and state.banked < job.pendingCollect.before then
        self.deliveries = self.deliveries + job.pendingCollect.before - state.banked
        self.adapter.stopDeliveryMovement()
        self.jobs = { phase = "idle" }
        self:report("jobs", "Banked jobs collected · preparing the next chain")
        return 1
    end

    -- A missing marker is not completion. Only banked progress can authorize the return trip.
    local complete = state.banked > 0 and (state.legCount == 0 or state.index >= state.legCount
        and (state.delivered or state.banked >= state.legCount))
    if complete then
        if job.phase ~= "collect" then
            self.adapter.stopDeliveryMovement()
            self.jobs = { phase = "collect" }
            job = self.jobs
        end
        if job.pendingCollect then
            if now < job.pendingCollect.retryAt then
                self:report("jobs", "Payout requested · waiting for banked count to update")
                return 0.5
            end
            if not job.pendingCollect.refreshRevision then
                job.pendingCollect.refreshRevision = state.revision
                self.adapter.refreshJobState()
                self:report("jobs", "Refreshing payout state before retrying")
                return 0.5
            end
            if state.revision <= job.pendingCollect.refreshRevision then
                self.adapter.refreshJobState()
                return 1
            end
        end
        if not self:travelToBoard(now, job, state.phase) then return 0.3 end
        self.adapter.collectJob()
        self.adapter.stopDeliveryMovement()
        job.collections = (job.collections or 0) + 1
        job.pendingCollect = { before = state.banked, retryAt = now + math.max(10, recoveryDelay(job.collections)) }
        self:report("jobs", string.format("Collecting %d banked jobs at the NPC", state.banked))
        return 0.5
    end
    if job.pendingCollect then
        self.adapter.stopDeliveryMovement()
        self.adapter.refreshJobState()
        self:report("jobs", "Payout state changed · synchronizing the active chain")
        return 1
    end

    if state.phase == "idle" or state.phase == "claimed" and state.banked == 0 then
        local ascensions = self.adapter.getAscensions()
        local capacity = Core.chainCapacity(ascensions)
        self.jobCapacity = capacity
        if state.legCount < capacity then
            pending = job.pendingClaim
            if pending then
                if now < pending.deadline then
                    self:report("jobs", string.format("%d/%d jobs accepted · waiting for slot %d", state.legCount, capacity, pending.before + 1))
                    return 0.3
                end
                if not pending.refreshRevision then
                    pending.refreshRevision = state.revision
                    self.adapter.refreshJobState()
                    self:report("jobs", "Claim delayed · refreshing accepted slots before retrying")
                    return 0.5
                end
                if state.revision <= pending.refreshRevision then
                    self.adapter.refreshJobState()
                    return 1
                end
                job.pendingClaim = nil
                job.claimReadyAt = now + 3
                self:report("jobs", "Slot still empty · retrying the best eligible job in 3s")
                return 0.5
            end
            if not self:travelToBoard(now, job, state.phase) then return 0.3 end
            job.claimReadyAt = job.claimReadyAt or now + 0.8
            if now < job.claimReadyAt then
                self:report("jobs", string.format("At board · filling %d available slots", capacity))
                return 0.3
            end
            if not self.adapter.isAtBoard() then job.claimReadyAt = nil; return 0.3 end
            local candidate = Core.bestJob(self.adapter.getAscensions())
            if state.legCount == 0 and state.phase == "idle" then
                self.adapter.claimJob(candidate.tier, candidate.jobType)
            elseif state.phase == "claimed" then
                -- Preserve the same payload as the successful first claim.
                self.adapter.appendJob(candidate.tier, candidate.jobType)
            else
                self:report("jobs", "Waiting for the board to accept another leg")
                return 0.5
            end
            self.adapter.stopDeliveryMovement()
            job.phase = "filling"
            job.pendingClaim = { before = state.legCount, deadline = now + 12 }
            self:report("jobs", string.format("Requested %s · slot %d/%d", candidate.name, state.legCount + 1, capacity))
            return 0.3
        end
    end

    if state.phase == "claimed" then job.departingToSpawn = true end
    if job.departingToSpawn and state.phase == "running"
        and (not self.adapter.isAtSpawnCenter or self.adapter.isAtSpawnCenter()) then
        self.adapter.stopDeliveryMovement()
        job.departingToSpawn = nil
        job.leaveStarted, job.nextLeave, job.leaveRetryAt, job.leaveRecoveries, job.departurePhase = nil, nil, nil, nil, nil
    end
    if job.departingToSpawn then
        job.phase = "leavePad"
        job.leaveStarted = job.leaveStarted or now
        if now - job.leaveStarted >= 12 then
            if not job.leaveRetryAt then
                self.adapter.stopDeliveryMovement()
                job.leaveRetryAt = now + recoveryDelay(job.leaveRecoveries)
            end
            if now < job.leaveRetryAt then
                self:report("jobs", "Spawn-center route stalled · retrying automatically", true, "leave_recovery")
                return 0.5
            end
            self:recoverMovement("claimed")
            job.leaveRecoveries = (job.leaveRecoveries or 0) + 1
            job.leaveRetryAt = nil
            job.leaveStarted = now
            job.nextLeave = now + 12
            job.departurePhase = state.phase
        end
        if now >= (job.nextLeave or 0) or job.departurePhase ~= state.phase then
            self.adapter.leaveJobPad()
            job.nextLeave = now + 4
            job.departurePhase = state.phase
        end
        self:report("jobs", string.format("%d jobs accepted · walking to spawn center", state.legCount))
        return 0.5
    end
    if state.phase ~= "running" then
        self.adapter.stopDeliveryMovement()
        self.adapter.refreshJobState()
        self:report("jobs", "Synchronizing job chain")
        return 1
    end
    if self.adapter.getPlayerState() ~= "RunWorld" then
        self.adapter.stopDeliveryMovement()
        if job.travel then job.travel.withinSince = nil end
        self:report("jobs", "Waiting for running world")
        return 0.5
    end
    if state.delivered or not state.drop then
        self.adapter.stopDeliveryMovement()
        job.travel = nil
        if now >= (job.nextRefresh or 0) then self.adapter.refreshJobState(); job.nextRefresh = now + 5 end
        self:report("jobs", string.format("%d jobs banked · waiting for the next destination", state.banked))
        return 0.5
    end
    job.phase = "delivery"
    local travel = job.travel
    if not travel or travel.index ~= state.index or not self.adapter.sameDropPoint(travel.drop, state.drop) then
        self.adapter.stopDeliveryMovement()
        travel = { index = state.index, drop = state.drop, lastProgress = now, attempts = 0 }
        job.travel = travel
        self.adapter.moveToDrop(state.drop)
    end
    local distance = self.adapter.getDropDistance(state.drop)
    assert(type(distance) == "number" and distance >= 0 and distance < math.huge, "Delivery distance unavailable")
    if travel.attempts >= Core.ARRIVAL_ATTEMPTS then
        if not travel.arrivalRetryAt then
            self.adapter.stopDeliveryMovement()
            travel.arrivalRetryAt = now + Core.ARRIVAL_RECOVERY_DELAY
        end
        if now < travel.arrivalRetryAt then
            self:report("jobs", "Arrival not acknowledged · retrying approach automatically", true, "arrival_recovery")
            return 0.5
        end
        self:recoverMovement("running", state.drop)
        travel.attempts, travel.arrivalRetryAt, travel.withinSince, travel.nextArrival = 0, nil, nil, nil
        travel.lastProgress, travel.bestDistance = now, distance
        self:report("jobs", "Approaching marker again before retrying arrival")
        return 0.3
    end
    if distance > Core.ARRIVAL_RADIUS then
        travel.withinSince = nil
        travel.bestDistance = travel.bestDistance or distance
        if distance < travel.bestDistance - 2 then
            travel.bestDistance, travel.lastProgress = distance, now
        end
        if not travel.retryAt and now - travel.lastProgress >= 12 then
            self.adapter.stopDeliveryMovement()
            travel.retryAt = now + recoveryDelay(travel.recoveries)
        end
        if travel.retryAt then
            if now < travel.retryAt then
                self:report("jobs", string.format("Travel stalled · %.0f studs away · automatic route retry pending", distance), true, "travel_stalled")
                return 0.5
            end
            self:recoverMovement("running", state.drop)
            travel.recoveries = (travel.recoveries or 0) + 1
            travel.retryAt, travel.bestDistance, travel.lastProgress = nil, distance, now
        else
            self.adapter.moveToDrop(state.drop)
        end
        local problem = self.adapter.getDeliveryMovementProblem and self.adapter.getDeliveryMovementProblem()
        self:report("jobs", problem or string.format("Leg %d/%d · %.0f studs to delivery", state.index, state.legCount, distance), problem ~= nil)
        return 0.3
    end
    travel.retryAt = nil
    travel.withinSince = travel.withinSince or now
    if now - travel.withinSince < Core.ARRIVAL_SETTLE then
        self:report("jobs", string.format("Leg %d/%d · settling inside delivery radius", state.index, state.legCount))
        return 0.3
    end
    if now >= (travel.nextArrival or 0) then
        self.adapter.reportArrival()
        travel.attempts = travel.attempts + 1
        travel.nextArrival = now + Core.ARRIVAL_RETRY
    end
    self:report("jobs", string.format("Leg %d/%d · arrival %d/%d sent; awaiting banked progress", state.index, state.legCount, travel.attempts, Core.ARRIVAL_ATTEMPTS))
    return 0.3
end

function Core:tick(now)
    if not self.running then return end
    if self.mode then
        self:run("movement", self.mode, now, function()
            if self.mode == "jobs" then return self:stepJobs(now) end
            if self.mode == "farm" then
                self.adapter.moveToTreadmill(self.treadmill)
                if self.farmPhase == "start" then
                    self.adapter.chargeStart()
                    self.farmPhase = "burst"
                    self:report("farm", "Charging on " .. self.treadmill)
                    return 0.4
                end
                self.adapter.chargeBurst()
                self.farmPhase = "start"
                self:report("farm", "Training on " .. self.treadmill)
                return 0.8
            end
            local found = self.adapter.collectNearestOrb()
            if found then self.orbRequests = self.orbRequests + 1 end
            self:report("orbs", found and "Nearby orb requested" or "No collectible orbs within 80 studs")
            return 0.8
        end)
    end
    for _, key in ipairs({ "race", "ascend", "buy" }) do
        if self.enabled[key] then
            self:run(key, key, now, function()
                if self.mode == "jobs" and key ~= "buy" then
                    self:report(key, "Paused while jobs control movement")
                    return 1
                end
                if key == "race" then
                    self.adapter.resetRace()
                    self:report(key, "Race reset requested")
                    return 4
                elseif key == "ascend" then
                    self.adapter.ascend()
                    self:report(key, "Ascension requested")
                    return 10
                end
                self.adapter.buyUpgrades()
                self:report(key, "Speed / Jump purchase requests sent")
                return 5
            end)
        end
    end
end

return Core

end)()

local Movement = (function()
-- Direction input for the game's RunWorld momentum controller; no position/velocity writes.
local Movement = {}
Movement.STOP_RADIUS = 35 -- Leave margin inside the game's 50-stud arrival radius.

function Movement.steer(dx, dy, dz, vx, vz, dt, stopRadius)
    stopRadius = stopRadius or Movement.STOP_RADIUS
    for _, value in ipairs({ dx, dy, dz, vx, vz, dt, stopRadius }) do
        assert(type(value) == "number" and value == value and math.abs(value) < math.huge, "Invalid movement sample")
    end
    local horizontal = math.sqrt(dx * dx + dz * dz)
    local distance = math.sqrt(horizontal * horizontal + dy * dy)
    if distance <= stopRadius then return 0, 0, "holding" end
    if horizontal < 1 then return 0, 0, "vertical" end
    local speed = math.sqrt(vx * vx + vz * vz)
    local horizontalStop = math.sqrt(math.max(0, stopRadius ^ 2 - dy * dy))
    local remaining = horizontal - horizontalStop
    -- The supplied worldMomentumStep clears its ramp when MoveDirection is zero.
    -- Brake before a high-speed frame can skip the entire arrival area.
    if speed > 1 and speed * math.max(dt, 1 / 240) + 8 >= remaining then
        return 0, 0, "braking"
    end
    return dx / horizontal, dz / horizontal, "moving"
end

return Movement

end)()

-- Roblox client adapter and UI. Core and Movement are embedded by scripts/build.py.
local Players = game:GetService("Players")
local ReplicatedStorage = game:GetService("ReplicatedStorage")
local TweenService = game:GetService("TweenService")
local Input = game:GetService("UserInputService")
local RunService = game:GetService("RunService")
local player = Players.LocalPlayer
assert(player, "Speedsters Beyond must be loaded on the client")
local playerGui = player:WaitForChild("PlayerGui", 10)
assert(playerGui, "PlayerGui did not load; retry after joining the game")

local shared = type(getgenv) == "function" and getgenv() or _G
local previous = shared.SpeedstersBeyondSession
if type(previous) == "table" and type(previous.destroy) == "function" then
    pcall(previous.destroy)
end
-- Quiesce the feature flags used by the user's original script when upgrading in-session.
for _, key in ipairs({ "AutoFarmState", "AutoOrbsState", "AutoJobState", "AutoRaceState", "AutoAscendState", "AutoBuyState" }) do
    if shared[key] ~= nil then shared[key] = false end
end

local parentGui = playerGui
local ok, hiddenGui = pcall(function()
    return type(gethui) == "function" and gethui() or game:GetService("CoreGui")
end)
if ok and hiddenGui then
    local probe = Instance.new("Folder")
    local writable = pcall(function() probe.Parent = hiddenGui end)
    probe:Destroy()
    if writable then parentGui = hiddenGui end
end
for _, parent in ipairs(parentGui == playerGui and { playerGui } or { playerGui, parentGui }) do
    local old = parent:FindFirstChild("SpeedstersBeyondHub")
    if old then
        local shutdown = old:FindFirstChild("Shutdown")
        if shutdown and shutdown:IsA("BindableEvent") then shutdown:Fire() end
        old:Destroy()
    end
end

local session = { alive = true, connections = {}, threads = {}, tweens = {}, renderBindings = {} }
shared.SpeedstersBeyondSession = session
local engine
local gui
local function connect(signal, callback)
    local connection = signal:Connect(function(...)
        if session.alive then callback(...) end
    end)
    table.insert(session.connections, connection)
    return connection
end
function session.destroy()
    if not session.alive then return end
    session.alive = false
    if engine then engine:destroy() end
    if session.cancelJobSnapshot then session.cancelJobSnapshot() end
    for _, name in ipairs(session.renderBindings) do RunService:UnbindFromRenderStep(name) end
    for _, connection in ipairs(session.connections) do connection:Disconnect() end
    for _, thread in ipairs(session.threads) do
        if coroutine.status(thread) ~= "dead" then pcall(task.cancel, thread) end
    end
    for _, tween in pairs(session.tweens) do tween:Cancel() end
    if gui then gui:Destroy() end
    if shared.SpeedstersBeyondSession == session then shared.SpeedstersBeyondSession = nil end
end

local palette = {
    bg = Color3.fromRGB(12, 16, 25),
    panel = Color3.fromRGB(18, 24, 37),
    card = Color3.fromRGB(23, 31, 46),
    stroke = Color3.fromRGB(45, 59, 78),
    text = Color3.fromRGB(237, 244, 255),
    muted = Color3.fromRGB(151, 170, 193),
    accent = Color3.fromRGB(83, 238, 205),
    blue = Color3.fromRGB(92, 156, 255),
    purple = Color3.fromRGB(164, 126, 255),
    warning = Color3.fromRGB(255, 193, 111),
    red = Color3.fromRGB(255, 116, 139),
}
local function create(class, props, parent)
    local object = Instance.new(class)
    for key, value in pairs(props or {}) do object[key] = value end
    object.Parent = parent
    return object
end
local function round(object, radius)
    local corner = object:FindFirstChildOfClass("UICorner") or create("UICorner", {}, object)
    corner.CornerRadius = UDim.new(0, radius or 12)
end
local function stroke(object, color, transparency)
    return create("UIStroke", { Color = color or palette.stroke, Transparency = transparency or 0, Thickness = 1 }, object)
end
local function animate(object, props)
    -- Keep at most one tween per widget; rapid toggles cannot finish out of order.
    if session.tweens[object] then session.tweens[object]:Cancel() end
    local tween = TweenService:Create(object, TweenInfo.new(0.16, Enum.EasingStyle.Quad, Enum.EasingDirection.Out), props)
    session.tweens[object] = tween
    tween:Play()
end
local function label(parent, text, size, color, bold)
    return create("TextLabel", {
        BackgroundTransparency = 1, BorderSizePixel = 0, Text = text,
        Font = bold and Enum.Font.GothamBold or Enum.Font.Gotham,
        TextSize = size or 13, TextColor3 = color or palette.text,
        TextXAlignment = Enum.TextXAlignment.Left, TextYAlignment = Enum.TextYAlignment.Center,
        TextTruncate = Enum.TextTruncate.AtEnd,
    }, parent)
end
local function button(parent, text, color)
    local item = create("TextButton", {
        BorderSizePixel = 0, BackgroundColor3 = color or palette.card,
        TextColor3 = palette.text, Font = Enum.Font.GothamMedium, TextSize = 13,
        Text = text, AutoButtonColor = false,
    }, parent)
    round(item, 8)
    connect(item.MouseEnter, function() animate(item, { BackgroundTransparency = 0.2 }) end)
    connect(item.MouseLeave, function() animate(item, { BackgroundTransparency = 0 }) end)
    return item
end
local function padding(parent, amount)
    create("UIPadding", {
        PaddingLeft = UDim.new(0, amount), PaddingRight = UDim.new(0, amount),
        PaddingTop = UDim.new(0, amount), PaddingBottom = UDim.new(0, amount),
    }, parent)
end
local function stack(parent, gap)
    create("UIListLayout", { SortOrder = Enum.SortOrder.LayoutOrder, Padding = UDim.new(0, gap or 10) }, parent)
end

local events = {}
local eventLabel
local startedAt = os.clock()
local function log(text, problem)
    table.insert(events, 1, string.format("%02d:%02d  %s", math.floor((os.clock() - startedAt) / 60), math.floor((os.clock() - startedAt) % 60), text))
    while #events > 6 do table.remove(events) end
    if eventLabel then eventLabel.Text = table.concat(events, "\n") end
    if problem then warn("[Speedsters Beyond] " .. text) end
end

local function remote(name)
    local folder = ReplicatedStorage:FindFirstChild("Remotes")
    local item = folder and folder:FindFirstChild(name)
    if not item or not item:IsA("RemoteEvent") then error("Missing RemoteEvent: " .. name, 0) end
    return item
end
local function send(name, ...)
    remote(name):FireServer(...)
end
local function root()
    local character = player.Character
    local part = character and character:FindFirstChild("HumanoidRootPart")
    local humanoid = character and character:FindFirstChildOfClass("Humanoid")
    if not part or not part:IsA("BasePart") or not humanoid or humanoid.Health <= 0 then
        error("Waiting for a living character", 0)
    end
    return part
end
local function location(value)
    local kind = typeof(value)
    if kind == "Vector3" then return CFrame.new(value) end
    if kind == "CFrame" then return value end
    if kind == "Instance" then
        if value:IsA("BasePart") then return value.CFrame end
        if value:IsA("Attachment") then return value.WorldCFrame end
        if value:IsA("Model") and value:FindFirstChildWhichIsA("BasePart", true) then return value:GetPivot() end
    end
    error("Unsupported or missing destination", 0)
end
local function moveTo(value, distance, offset)
    local part = root()
    local target = location(value)
    if (part.Position - target.Position).Magnitude > distance then
        part.CFrame = target + Vector3.new(0, offset or 3, 0)
        part.AssemblyLinearVelocity = Vector3.zero
        part.AssemblyAngularVelocity = Vector3.zero
    end
end

local controller = { script = nil, value = nil, loading = false, retry = 0, failure = nil }
local function jobsController()
    local scripts = player:FindFirstChild("PlayerScripts")
    local controllers = scripts and scripts:FindFirstChild("Controllers")
    local module = controllers and controllers:FindFirstChild("JobsController")
    if not module or not module:IsA("ModuleScript") then error("Waiting for JobsController", 0) end
    if controller.script ~= module then
        controller = { script = module, value = nil, loading = false, retry = 0, failure = nil }
    end
    local current = controller
    if current.value then return current.value end
    if not current.loading and os.clock() >= current.retry then
        current.loading = true
        current.started = os.clock()
        -- require can yield; keep it out of the shared automation loop.
        local thread = task.spawn(function()
            local loaded, result = pcall(require, module)
            if not session.alive or controller ~= current then return end
            current.loading = false
            current.retry = os.clock() + 10
            if loaded and type(result) == "table" and type(result.GetDropPoint) == "function" then
                current.value = result
            else
                current.failure = loaded and "JobsController has no GetDropPoint method" or "JobsController could not load"
                log(current.failure, true)
            end
        end)
        table.insert(session.threads, thread)
    end
    if current.value then return current.value end
    if current.loading and os.clock() - current.started > 10 then
        error("JobsController is still loading; rejoin if this persists", 0)
    end
    error(current.failure or "Loading JobsController", 0)
end

local jobSnapshots = { revision = 0, nextRequest = 0 }
local function cancelSnapshotRequest()
    local thread = jobSnapshots.thread
    jobSnapshots.thread = nil
    jobSnapshots.loading = false
    if thread and coroutine.status(thread) ~= "dead" then pcall(task.cancel, thread) end
end
session.cancelJobSnapshot = cancelSnapshotRequest
local function adoptJobSnapshot(snapshot)
    if type(snapshot) ~= "table" or type(snapshot.banked) ~= "number" then
        jobSnapshots.failure = "Invalid jobs snapshot"
        jobSnapshots.value = nil
        return
    end
    local contract = snapshot.contract
    if contract ~= nil and contract ~= false and (type(contract) ~= "table" or type(contract.legs) ~= "table" or type(contract.index) ~= "number") then
        jobSnapshots.failure = "Job chain snapshot is incomplete"
        jobSnapshots.value = nil
        return
    end
    jobSnapshots.value = {
        legCount = contract and #contract.legs or 0,
        index = contract and contract.index or 0,
        banked = snapshot.banked,
        drops = {},
    }
    if contract then
        for index, leg in ipairs(contract.legs) do
            if type(leg) == "table" and leg.dropPoint ~= nil then
                local valid, point = pcall(location, leg.dropPoint)
                if valid then jobSnapshots.value.drops[index] = point end
            end
        end
    end
    jobSnapshots.revision = jobSnapshots.revision + 1
    jobSnapshots.failure = nil
end
local function watchJobSnapshots()
    local event = remote("JobsStateChanged")
    if jobSnapshots.event ~= event then
        cancelSnapshotRequest()
        if jobSnapshots.connection then jobSnapshots.connection:Disconnect() end
        jobSnapshots.event = event
        jobSnapshots.value = nil
        jobSnapshots.nextRequest = 0
        jobSnapshots.connection = connect(event.OnClientEvent, adoptJobSnapshot)
    end
end
local function refreshJobState()
    jobsController()
    watchJobSnapshots()
    if jobSnapshots.loading and os.clock() - jobSnapshots.started >= 8 then
        cancelSnapshotRequest()
        jobSnapshots.nextRequest = os.clock() + 3
    end
    if jobSnapshots.loading or os.clock() < jobSnapshots.nextRequest then return end
    local folder = ReplicatedStorage:FindFirstChild("Remotes")
    local request = folder and folder:FindFirstChild("GetJobsSnapshot")
    assert(request and request:IsA("RemoteFunction"), "Missing RemoteFunction: GetJobsSnapshot")
    local revision, event = jobSnapshots.revision, jobSnapshots.event
    jobSnapshots.loading = true
    jobSnapshots.started = os.clock()
    jobSnapshots.thread = task.spawn(function()
        local loaded, snapshot = pcall(function() return request:InvokeServer() end)
        if not session.alive or jobSnapshots.event ~= event then return end
        jobSnapshots.loading = false
        jobSnapshots.nextRequest = os.clock() + 2
        -- An event received while InvokeServer yielded is newer than that request's view.
        if revision ~= jobSnapshots.revision then return end
        if loaded then adoptJobSnapshot(snapshot)
        else jobSnapshots.failure = "Could not refresh jobs snapshot" end
    end)
end
local function activeDelivery(jobs, snapshot, phase)
    local delivered = jobs:HasDeliveredCurrent()
    if phase ~= "running" then return nil, delivered end
    local point = snapshot and snapshot.drops[snapshot.index]
    if point then
        -- The client can keep the previous marker/completion flag while adopting a
        -- newer server leg. Follow the server-selected point and banked progress.
        return point, snapshot.banked >= snapshot.index
    end
    local live = jobs:GetDropPoint()
    return live and location(live) or nil, delivered
end
local function getJobState()
    root()
    local jobs = jobsController()
    watchJobSnapshots()
    if not jobSnapshots.value then refreshJobState() end
    local snapshot = jobSnapshots.value
    assert(snapshot, jobSnapshots.failure or "Loading accepted jobs")
    for _, name in ipairs({ "GetPhase", "HasDeliveredCurrent" }) do
        assert(type(jobs[name]) == "function", "JobsController API unavailable: " .. name)
    end
    local phase = jobs:GetPhase()
    local drop, delivered = activeDelivery(jobs, snapshot, phase)
    return {
        phase = phase, legCount = snapshot.legCount, banked = snapshot.banked, index = snapshot.index,
        delivered = delivered, revision = jobSnapshots.revision, drop = drop,
    }
end

-- Default Roblox controls run at Input (100); the supplied SpeedstersMovement runs
-- at Input+1 (101). While steering, suspend only default player input, write MoveDirection
-- at 100, and let the game's own momentum step apply its normal velocity at 101.
local controlsCache = { loading = false, retry = 0 }
local driveGoal
local ownedControls
local movementProblem
local movementBindingError
local function clearNavigation(goal)
    local navigation = goal and goal.navigation
    if not navigation then return end
    goal.navigation = nil
    if navigation.thread and coroutine.status(navigation.thread) ~= "dead" then pcall(task.cancel, navigation.thread) end
    if navigation.blockedConnection then navigation.blockedConnection:Disconnect() end
    if navigation.path then pcall(function() navigation.path:Destroy() end) end
end

local function findRoute(goal, part)
    local navigation = { loading = true, started = os.clock(), index = 2 }
    goal.navigation = navigation
    local origin = part.Position
    local delta = goal.target - origin
    -- Plan only a local segment: far delivery markers can be tens of thousands of studs away.
    local destination = origin + delta * math.min(1, 192 / math.max(delta.Magnitude, 1))
    navigation.thread = task.spawn(function()
        local found, failure = pcall(function()
            local path = game:GetService("PathfindingService"):CreatePath({
                AgentRadius = math.max(2, part.Size.X / 2),
                AgentHeight = math.max(5, goal.humanoid.HipHeight * 2 + part.Size.Y),
                AgentCanJump = true, WaypointSpacing = 6,
            })
            navigation.path = path
            path:ComputeAsync(origin, destination)
            if not session.alive or driveGoal ~= goal or goal.navigation ~= navigation then return end
            assert(path.Status == Enum.PathStatus.Success, "No walkable route available yet")
            local waypoints = path:GetWaypoints()
            assert(#waypoints >= 2, "Route has no next waypoint")
            navigation.waypoints = waypoints
            navigation.blockedConnection = path.Blocked:Connect(function(index)
                if index >= navigation.index then navigation.blocked = true end
            end)
        end)
        if not session.alive or driveGoal ~= goal or goal.navigation ~= navigation then return end
        navigation.loading = false
        if not found then
            navigation.failure = tostring(failure)
            navigation.retryAt = os.clock() + 3
        end
    end)
end
local function playerControls()
    if controlsCache.value then return controlsCache.value end
    if not controlsCache.loading and os.clock() >= controlsCache.retry then
        local scripts = player:FindFirstChild("PlayerScripts")
        local module = scripts and scripts:FindFirstChild("PlayerModule")
        if not module or not module:IsA("ModuleScript") then error("PlayerModule controls are unavailable", 0) end
        controlsCache.loading = true
        local thread = task.spawn(function()
            local loaded, result = pcall(function()
                local api = require(module)
                assert(type(api) == "table" and type(api.GetControls) == "function", "PlayerModule has no GetControls")
                local controls = api:GetControls()
                assert(type(controls) == "table" and type(controls.Enable) == "function" and type(controls.Disable) == "function", "Player controls cannot be acquired")
                assert(type(controls.controlsEnabled) == "boolean", "Player controls do not expose their enabled state")
                return controls
            end)
            if not session.alive then return end
            controlsCache.loading = false
            controlsCache.retry = os.clock() + 5
            if loaded then controlsCache.value = result else controlsCache.failure = tostring(result) end
        end)
        table.insert(session.threads, thread)
    end
    if controlsCache.value then return controlsCache.value end
    error(controlsCache.failure or "Loading player movement controls", 0)
end
local function stopDeliveryMovement()
    local previous = driveGoal
    driveGoal = nil
    clearNavigation(previous)
    if previous and previous.humanoid.Parent then
        pcall(function() previous.humanoid:Move(Vector3.zero, false) end)
    end
    if ownedControls then
        local controls = ownedControls
        ownedControls = nil
        local restored, err = pcall(function() controls:Enable() end)
        if not restored then log("Could not restore player input: " .. tostring(err), true) end
    end
end
local function beginDrive(target, phase, stopRadius, kind)
    kind = kind or "drop"
    if movementBindingError then error(movementBindingError, 0) end
    local part = root()
    local playerState = part.Parent:GetAttribute("PlayerState")
    if playerState ~= "RunWorld" and not (kind ~= "drop" and playerState == "Main") then
        stopDeliveryMovement()
        error("Waiting for RunWorld movement", 0)
    end
    local controls = playerControls()
    if ownedControls ~= controls then
        stopDeliveryMovement()
        if not controls.controlsEnabled then error("Player controls are disabled by the game; waiting", 0) end
        ownedControls = controls
        local disabled, err = pcall(function() controls:Disable() end)
        if not disabled then stopDeliveryMovement(); error(tostring(err), 0) end
    end
    local changed = not driveGoal or driveGoal.character ~= part.Parent or driveGoal.phase ~= phase
        or driveGoal.kind ~= kind or (driveGoal.target - target).Magnitude > 2
    if changed then
        clearNavigation(driveGoal)
        driveGoal = {
            target = target, phase = phase, kind = kind, stopRadius = stopRadius or Movement.STOP_RADIUS,
            character = part.Parent, humanoid = part.Parent:FindFirstChildOfClass("Humanoid"),
        }
        movementProblem = nil
    end
    return true
end

local function enableRouteRecovery()
    assert(driveGoal, "Movement goal unavailable")
    driveGoal.routing = true
    if driveGoal.kind == "drop" then driveGoal.stopRadius = 8 end
end
local function steerDelivery(dt)
    local goal = driveGoal
    if not goal or not session.alive then return end
    if player.Character ~= goal.character or goal.humanoid.Health <= 0 then
        stopDeliveryMovement()
        return
    end
    local playerState = goal.character:GetAttribute("PlayerState")
    if playerState ~= "RunWorld" and not (goal.kind ~= "drop" and playerState == "Main") then
        movementProblem = "Waiting for RunWorld movement"
        stopDeliveryMovement()
        return
    end
    local jobs = controller.value
    if not jobs or type(jobs.GetPhase) ~= "function" or jobs:GetPhase() ~= goal.phase then
        stopDeliveryMovement()
        return
    end
    local target = goal.target
    if goal.kind == "drop" then
        local live, delivered = activeDelivery(jobs, jobSnapshots.value, goal.phase)
        if not live or delivered then stopDeliveryMovement(); return end
        target = live.Position
        if (goal.target - target).Magnitude > 2 then
            clearNavigation(goal)
            goal.target = target
        end
    end
    local part = root()
    local stopRadius = goal.stopRadius
    if goal.routing and (target - part.Position).Magnitude > stopRadius then
        local navigation = goal.navigation
        if navigation and (navigation.blocked or navigation.loading and os.clock() - navigation.started >= 8
            or navigation.failure and os.clock() >= navigation.retryAt) then
            clearNavigation(goal)
            navigation = nil
        end
        if not navigation then
            findRoute(goal, part)
            navigation = goal.navigation
        end
        if navigation.loading or navigation.failure then
            goal.humanoid:Move(Vector3.zero, false)
            movementProblem = navigation.failure and "Route unavailable · retrying automatically" or "Finding a walkable route"
            return
        end
        local waypoint = navigation.waypoints[navigation.index]
        while waypoint and (part.Position - waypoint.Position).Magnitude <= 6 do
            navigation.index = navigation.index + 1
            waypoint = navigation.waypoints[navigation.index]
        end
        if not waypoint then
            clearNavigation(goal)
            goal.humanoid:Move(Vector3.zero, false)
            return
        end
        target = waypoint.Position
        stopRadius = 4
        if waypoint.Action == Enum.PathWaypointAction.Jump and navigation.jumpedIndex ~= navigation.index
            and (part.Position - target).Magnitude <= 14 then
            goal.humanoid.Jump = true
            navigation.jumpedIndex = navigation.index
        end
    end
    local delta = target - part.Position
    local velocity = part.AssemblyLinearVelocity
    local x, z, state = Movement.steer(delta.X, delta.Y, delta.Z, velocity.X, velocity.Z, dt, stopRadius)
    movementProblem = state == "vertical" and "Vertical route needed · automatic recovery pending" or nil
    goal.humanoid:Move(Vector3.new(x, 0, z), false)
end
local steeringBinding = "SpeedstersBeyondDeliveryInput"
local bound, bindingError = pcall(function()
    RunService:BindToRenderStep(steeringBinding, Enum.RenderPriority.Input.Value, function(dt)
        if not session.alive then return end
        local steered, err = pcall(steerDelivery, dt)
        if not steered then
            movementProblem = "Movement input unavailable: " .. tostring(err)
            stopDeliveryMovement()
        end
    end)
end)
if bound then
    table.insert(session.renderBindings, steeringBinding)
else
    movementBindingError = "Cannot schedule delivery input: " .. tostring(bindingError)
end

local ascensionOverride
local function readAscensions()
    if ascensionOverride ~= nil then return ascensionOverride, "manual" end
    local detected
    local function consider(value)
        local number = tonumber(value)
        if not number or number < 0 or number >= math.huge or number % 1 ~= 0 then return end
        if detected ~= nil and detected ~= number then
            error("Conflicting ascension counts · enter your current count below", 0)
        end
        detected = number
    end
    consider(player:GetAttribute("Ascensions"))
    consider(player:GetAttribute("Ascension"))
    -- Attribute and ValueObject paths differ across game versions. Never default a missing stat to 0.
    for _, item in ipairs(player:GetDescendants()) do
        local name = string.lower(item.Name)
        if (name == "ascensions" or name == "ascension") and (item:IsA("IntValue") or item:IsA("NumberValue") or item:IsA("StringValue")) then
            consider(item.Value)
        end
    end
    if detected == nil then error("Ascensions unavailable · enter your current count below", 0) end
    return detected, "detected"
end

local orbParts = {}
local orbCooldown = setmetatable({}, { __mode = "k" })
local orbsIndexed = false
local function indexOrb(object)
    if object:IsA("BasePart") and string.find(string.lower(object.Name), "orb", 1, true) then
        orbParts[object] = true
    end
end
local function ensureOrbIndex()
    if orbsIndexed then return end
    orbsIndexed = true
    connect(workspace.DescendantAdded, indexOrb)
    connect(workspace.DescendantRemoving, function(object) orbParts[object] = nil end)
    for _, object in ipairs(workspace:GetDescendants()) do indexOrb(object) end
end

local returnOrigin
local spawnCenterCache = { retryAt = 0 }
local function spawnCenterPosition()
    local part = root()
    local function usable(object)
        return object and object:IsDescendantOf(workspace)
            and (not object:IsA("SpawnLocation") or object.Enabled ~= false
                and (object.Neutral ~= false or object.TeamColor == player.TeamColor))
    end
    local spawn = player.RespawnLocation
    if not usable(spawn) then spawn = spawnCenterCache.object end
    if not usable(spawn) then
        spawn = nil
        if os.clock() >= spawnCenterCache.retryAt then
            spawnCenterCache.retryAt = os.clock() + 3
            local named = workspace:FindFirstChild("SpawnCenter", true)
            if named and pcall(location, named) then spawn = named end
            if not spawn then
                local geometry = workspace:FindFirstChild("ServerGeometry")
                local board = workspace:FindFirstChild("JobsPart") or (geometry and geometry:FindFirstChild("JobsPart"))
                local origin = board and location(board).Position or part.Position
                local nearest = math.huge
                for _, object in ipairs(workspace:GetDescendants()) do
                    if object:IsA("SpawnLocation") and usable(object) then
                        local distance = (object.Position - origin).Magnitude
                        if distance < nearest then spawn, nearest = object, distance end
                    end
                end
            end
            spawnCenterCache.object = spawn
        end
    end
    assert(spawn, "Waiting for the spawn center or an active SpawnLocation to load")
    local target = location(spawn).Position
    if spawn:IsA("SpawnLocation") then
        local humanoid = part.Parent:FindFirstChildOfClass("Humanoid")
        target = target + Vector3.new(0, spawn.Size.Y / 2 + humanoid.HipHeight + part.Size.Y / 2, 0)
    end
    return target
end
local nextWarning = {}
local reportedIssue = {}
engine = Core.new({
    onStatus = function(key, text, problem, issue)
        -- UI status stays live; changing distances must not flood the console/feed.
        if not problem then
            reportedIssue[key] = nil
            return
        end
        if issue and reportedIssue[key] == issue then return end
        if issue then
            reportedIssue[key] = issue
            nextWarning[key] = os.clock() + 5
            log(key .. ": " .. text, true)
            return
        end
        if problem and os.clock() >= (nextWarning[key] or -math.huge) then
            nextWarning[key] = os.clock() + 5
            log(key .. ": " .. text, true)
        end
    end,
    moveToTreadmill = function(name)
        remote("ChargeStart")
        remote("ChargeBurst")
        local folder = workspace:FindFirstChild("Treadmills")
        local target = folder and folder:FindFirstChild(name)
        if not target then error("Treadmill " .. name .. " is unavailable; select another", 0) end
        moveTo(target, 7, 3)
    end,
    chargeStart = function() send("ChargeStart") end,
    chargeBurst = function() send("ChargeBurst") end,
    getAscensions = readAscensions,
    getJobState = getJobState,
    refreshJobState = refreshJobState,
    getPlayerState = function()
        return player.Character and player.Character:GetAttribute("PlayerState")
    end,
    leaveJobPad = function()
        beginDrive(spawnCenterPosition(), jobsController():GetPhase(), 6, "pad")
    end,
    isAtSpawnCenter = function() return (root().Position - spawnCenterPosition()).Magnitude <= 6 end,
    moveToBoard = function(phase)
        local geometry = workspace:FindFirstChild("ServerGeometry")
        local board = workspace:FindFirstChild("JobsPart") or (geometry and geometry:FindFirstChild("JobsPart"))
        if not board then error("Waiting for the job board to load", 0) end
        -- Verify all three endpoints before accepting a delivery we cannot finish.
        remote("ClaimJob")
        remote("ReportJobArrival")
        remote("CollectJob")
        local target = location(board).Position
        local distance = (root().Position - target).Magnitude
        beginDrive(target, phase or jobsController():GetPhase(), 6, "board")
        return distance <= 10, distance
    end,
    shouldReturnToSpawn = function()
        local geometry = workspace:FindFirstChild("ServerGeometry")
        local board = workspace:FindFirstChild("JobsPart") or (geometry and geometry:FindFirstChild("JobsPart"))
        if not board then error("Waiting for the job board to load", 0) end
        return (root().Position - location(board).Position).Magnitude > 200
    end,
    returnToSpawn = function()
        local part = root()
        local state = part.Parent:GetAttribute("PlayerState")
        assert(state == "Main" or state == "RunWorld" or state == "Race", "Waiting until Return to Spawn is available")
        returnOrigin = { character = part.Parent, position = part.Position }
        send("ReturnToSpawn")
    end,
    hasReturnedToSpawn = function()
        local part = root()
        return returnOrigin ~= nil and (part.Parent ~= returnOrigin.character or (part.Position - returnOrigin.position).Magnitude > 15)
    end,
    claimJob = function(tier, slot) send("ClaimJob", tier, slot) end,
    appendJob = function(tier, jobType) send("ClaimJob", tier, jobType) end,
    isAtBoard = function()
        local geometry = workspace:FindFirstChild("ServerGeometry")
        local board = workspace:FindFirstChild("JobsPart") or (geometry and geometry:FindFirstChild("JobsPart"))
        return board ~= nil and (root().Position - location(board).Position).Magnitude <= 10
    end,
    moveToDrop = function(drop) return beginDrive(location(drop).Position, "running") end,
    sameDropPoint = function(first, second) return (location(first).Position - location(second).Position).Magnitude <= 2 end,
    recoverJobMovement = function(phase, drop)
        if phase == "running" then
            beginDrive(location(drop).Position, phase, 8)
        elseif phase == "claimed" then
            beginDrive(spawnCenterPosition(), jobsController():GetPhase(), 6, "pad")
        else
            local geometry = workspace:FindFirstChild("ServerGeometry")
            local board = workspace:FindFirstChild("JobsPart") or (geometry and geometry:FindFirstChild("JobsPart"))
            if not board then error("Waiting for the job board to load", 0) end
            beginDrive(location(board).Position, jobsController():GetPhase(), 6, "board")
        end
        enableRouteRecovery()
    end,
    getDeliveryMovementProblem = function() return movementProblem end,
    getDropDistance = function(drop) return (root().Position - location(drop).Position).Magnitude end,
    stopDeliveryMovement = stopDeliveryMovement,
    reportArrival = function() send("ReportJobArrival") end,
    collectJob = function() send("CollectJob") end,
    collectNearestOrb = function()
        local origin = root().Position
        local collect = remote("OrbCollect")
        ensureOrbIndex()
        local nearest, nearestDistance = nil, 80
        local now = os.clock()
        for object in pairs(orbParts) do
            if object:IsDescendantOf(workspace) and now >= (orbCooldown[object] or 0) then
                local distance = (origin - object.Position).Magnitude
                if distance < nearestDistance then nearest, nearestDistance = object, distance end
            end
        end
        if not nearest then return false end
        moveTo(nearest, 3, 0)
        collect:FireServer(nearest)
